body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

main {
  width: 100%;
}

.container {
  max-width: 500px;
  margin: 0 auto;
  background: white;
  border-radius: 12px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.1);
  padding: 40px;
}

h1 {
  font-size: 28px;
  color: #1a202c;
  margin-bottom: 32px;
  text-align: center;
  font-weight: 600;
}

.form {
  display: flex;
  flex-direction: column;
  gap: 32px;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

fieldset {
  border: none;
  padding: 0;
  margin: 0;
}

legend {
  font-size: 16px;
  font-weight: 600;
  color: #2d3748;
  margin-bottom: 16px;
  padding: 0;
  display: block;
  width: 100%;
}

legend span {
  color: #e53e3e;
}

.radio-option {
  display: flex;
  align-items: center;
  padding: 12px 16px;
  border: 2px solid #e2e8f0;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
  gap: 12px;
}

.radio-option:hover {
  border-color: #cbd5e0;
  background-color: #f7fafc;
}

.radio-option input[type="radio"] {
  cursor: pointer;
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  accent-color: #3182ce;
}

.radio-option input[type="radio"]:focus-visible {
  outline: 2px solid #3182ce;
  outline-offset: 2px;
}

.radio-option label {
  cursor: pointer;
  font-size: 16px;
  color: #2d3748;
  flex: 1;
  margin: 0;
}

.submit-btn {
  background-color: #3182ce;
  color: white;
  border: none;
  padding: 12px 24px;
  font-size: 16px;
  font-weight: 600;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
  width: 100%;
}

.submit-btn:hover {
  background-color: #2c5aa0;
}

.submit-btn:active {
  transform: translateY(1px);
}

.submit-btn:focus-visible {
  outline: 2px solid #3182ce;
  outline-offset: 2px;
}

.submit-btn:disabled {
  background-color: #cbd5e0;
  cursor: not-allowed;
}

/* Success message */
.success-message {
  display: none;
  padding: 12px 16px;
  background-color: #f0fff4;
  border: 1px solid #9ae6b4;
  border-radius: 8px;
  color: #22543d;
  margin-bottom: 16px;
  font-size: 14px;
}

.success-message.show {
  display: block;
}

/* Responsive design */
@media (max-width: 480px) {
  .container {
    padding: 24px;
  }

  h1 {
    font-size: 24px;
    margin-bottom: 24px;
  }

  legend {
    font-size: 15px;
  }

  .radio-option {
    padding: 10px 12px;
  }

  .radio-option input[type="radio"] {
    width: 18px;
    height: 18px;
  }

  .radio-option label {
    font-size: 15px;
  }

  .submit-btn {
    padding: 10px 16px;
    font-size: 15px;
  }
}

/* Forced Colors support */
@media (forced-colors: active) {
  .container {
    border: 1px solid CanvasText;
  }

  .radio-option {
    border: 2px solid ButtonBorder;
  }

  .radio-option:hover {
    background-color: Highlight;
  }

  .submit-btn {
    border: 1px solid ButtonBorder;
  }

  .submit-btn:focus-visible {
    outline: 2px solid Highlight;
  }
}
