+document.addEventListener('DOMContentLoaded', () => {
+  const form = document.getElementById('notificationForm');
+  
+  form.addEventListener('submit', (e) => {
+    e.preventDefault();
+    
+    const selectedValue = document.querySelector('input[name="notification"]:checked')?.value;
+    
+    if (selectedValue) {
+      console.log(`User preference saved: ${selectedValue}`);
+      showSuccessMessage(selectedValue);
+    }
+  });
+});
+
+function showSuccessMessage(preference) {
+  const preferenceText = {
+    email: 'Email',
+    sms: 'SMS',
+    push: 'Push Notifications'
+  };
+  
+  const form = document.getElementById('notificationForm');
+  
+  // Remove existing success message if present
+  const existingMessage = form.querySelector('.success-message');
+  if (existingMessage) {
+    existingMessage.remove();
+  }
+  
+  // Create and insert success message
+  const message = document.createElement('div');
+  message.className = 'success-message show';
+  message.setAttribute('role', 'status');
+  message.setAttribute('aria-live', 'polite');
+  message.textContent = `✓ Notification preference saved: ${preferenceText[preference]}`;
+  
+  form.insertBefore(message, form.firstChild);
+  
+  // Auto-remove after 4 seconds
+  setTimeout(() => {
+    message.remove();
+  }, 4000);
+}
+
')

